    TrapCode,
    engine::{ResumableHostTrapError, ResumableOutOfFuelError, TranslationError},
    module::ReadError,
};''', '''use crate::{
    TrapCode,
    engine::{Coredump, ResumableHostTrapError, ResumableOutOfFuelError, TranslationError},
    module::ReadError,
};''')
s = s.replace('''/// The generic Wasmi root error type.
#[derive(Debug)]
pub struct Error {
    /// The underlying kind of the error and its specific information.
    kind: Box<ErrorKind>,
}''', '''/// The inner data of a [`Error`].
#[derive(Debug)]
struct ErrorInner {
    /// The underlying kind of the error and its specific information.
    kind: ErrorKind,
    /// An optional coredump generated upon a Wasm trap.
    coredump: Option<Coredump>,
}

/// The generic Wasmi root error type.
#[derive(Debug)]
pub struct Error {
    /// The inner data of the [`Error`].
    inner: Box<ErrorInner>,
}''')
s = s.replace('''    fn from_kind(kind: ErrorKind) -> Self {
        Self {
            kind: Box::new(kind),
        }
    }''', '''    fn from_kind(kind: ErrorKind) -> Self {
        Self {
            inner: Box::new(ErrorInner {
                kind,
                coredump: None,
            }),
        }
    }''')
s = s.replace('''    pub fn kind(&self) -> &ErrorKind {
        &self.kind
    }''', '''    pub fn kind(&self) -> &ErrorKind {
        &self.inner.kind
    }''')
s = s.replace('''    /// Returns the classic `i32` exit program code of a `Trap` if any.''', '''    /// Returns the coredump bytes if this [`Error`] was generated by a Wasm trap
    /// with coredump generation enabled.
    ///
    /// # Note
    ///
    /// - Coredumps are only generated for Wasm traps.
    /// - Coredump generation must be enabled via
    ///   [`Config::generate_coredump`](crate::Config::generate_coredump).
    ///
    /// [`Config`]: crate::Config
    pub fn coredump(&self) -> Option<&[u8]> {
        self.inner.coredump.as_ref().map(Coredump::bytes)
    }

    /// Attaches the given `coredump` to `self`.
    pub(crate) fn set_coredump(&mut self, coredump: Coredump) {
        self.inner.coredump = Some(coredump);
    }

    /// Returns a mutable reference to the attached coredump if any.
    pub(crate) fn coredump_mut(&mut self) -> Option<&mut Coredump> {
        self.inner.coredump.as_mut()
    }

    /// Returns the classic `i32` exit program code of a `Trap` if any.''')
s = s.replace('''        self.kind
            .as_host()
            .and_then(<dyn HostError + 'static>::downcast_ref)''', '''        self.inner
            .kind
            .as_host()
            .and_then(<dyn HostError + 'static>::downcast_ref)''')
s = s.replace('''        self.kind
            .as_host_mut()
            .and_then(<dyn HostError + 'static>::downcast_mut)''', '''        self.inner
            .kind
            .as_host_mut()
            .and_then(<dyn HostError + 'static>::downcast_mut)''')
s = s.replace('''        self.kind
            .into_host()
            .and_then(|error| error.downcast().ok())''', '''        self.inner
            .kind
            .into_host()
            .and_then(|error| error.downcast().ok())''')
s = s.replace('''        Display::fmt(&self.kind, f)''', '''        Display::fmt(&self.inner.kind, f)''')
p.write_text(s)
print("error.rs done")

